def generate(seed):
    r = random.Random(seed)
    while True:
        R = r.choice([3, 3, 3, 4])
        g = [r.randint(2, 6 if R < 4 else 4) for _ in range(R)]
        if len(set(g)) > 1 and 6 <= sum(g) <= 11:
            break
    while True:
        a = [r.choice([2, 2, 3, 3, 4]) for _ in range(R - 1)]
        d = [r.randrange(x) for x in a]
        if 2 <= sum(d) <= R + 1 and max(x - y for x, y in zip(a, d)) < 4:
            break
    return ("".join(map(str, g)) + "/" + "".join(map(str, a)) + "/"
            + "".join(map(str, d)))

